var W = 1630, H = 615;
var D = SVG().addTo(document.getElementById('container')).size('100%', '100%');
D.viewbox(0, 0, W, H);

var ORANGE = '#d2714d', ORANGE_DIM = '#eccbbd', TEAL = '#a0d9d3', TEAL_DIM = '#e6f4f2';
var INK = '#1a1a1a', ACCENT = '#e5a12c', FAINT = '#dcdcdc', GREY = '#b9b9b9';

var base = { '1': [443, 208], '2': [117, 172], '3': [308, 100], '4': [158, 430], '5': [33, 325], '6': [455, 430] };
var offA = [22, 18], offB = [602, 18];
var edges = [['1', '3'], ['2', '3'], ['2', '5'], ['1', '5'], ['1', '4'], ['4', '5'], ['1', '6'], ['4', '6']];

function ekey(e) { return e[0] + '/' + e[1]; }
var edgeOf = {};
edges.forEach(function (e) { edgeOf[ekey(e)] = e; });

var incident = {};
edges.forEach(function (e) {
  [0, 1].forEach(function (i) { (incident[e[i]] = incident[e[i]] || []).push(ekey(e)); });
});
var lgEdges = [];
['1', '2', '3', '4', '5', '6'].forEach(function (v) {
  var L = incident[v];
  for (var i = 0; i < L.length; i++) for (var j = i + 1; j < L.length; j++) lgEdges.push({ a: L[i], b: L[j], v: v });
});
var lgNbr = {};
edges.forEach(function (e) { lgNbr[ekey(e)] = []; });
lgEdges.forEach(function (le) {
  lgNbr[le.a].push({ o: le.b, v: le.v });
  lgNbr[le.b].push({ o: le.a, v: le.v });
});

var cliqueColor = { '1': '#2f6fd0', '2': '#8e44ad', '3': '#16a085', '4': '#e07b39', '5': '#c0392b', '6': '#6c7a89' };

var posC = {
  '2/3': [1382, 155], '1/3': [1548, 155], '2/5': [1228, 262], '1/5': [1408, 280],
  '1/4': [1458, 330], '1/6': [1582, 330], '4/5': [1247, 388], '4/6': [1458, 432]
};

function pA(v) { return [base[v][0] + offA[0], base[v][1] + offA[1]]; }
function pB(v) { return [base[v][0] + offB[0], base[v][1] + offB[1]]; }
function midB(e) { var a = pB(e[0]), b = pB(e[1]); return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]; }

/* ---------- static chrome ---------- */
