  var t = g.text(s).font({ family: 'sans-serif', size: size, anchor: anchor || 'middle', weight: weight || 'normal' }).fill(color || INK);
  if (anchor === 'start') { t.attr('x', x); t.cy(y); t.attr('text-anchor', 'start'); t.attr('x', x); }
  else { t.cx(x); t.cy(y); }
  return t;
}
