D.viewbox(0, 0, W, H);

var ORANGE = '#d2714d', ORANGE_DIM = '#eccbbd', TEAL = '#a0d9d3', TEAL_DIM = '#e6f4f2';
var INK = '#1a1a1a', ACCENT = '#e5a12c', FAINT = '#dcdcdc', GREY = '#b9b9b9';

var base = { '1': [443, 208], '2': [117, 172], '3': [308, 100], '4': [158, 430], '5': [33, 325], '6': [455, 430] };
var offA = [22, 18], offB = [602, 18];
var edges = [['1', '3'], ['2', '3'], ['2', '5'], ['1', '5'], ['1', '4'], ['4', '5'], ['1', '6'], ['4', '6']];

function ekey(e) { return e[0] + '/' + e[1]; }
var edgeOf = {};
edges.forEach(function (e) { edgeOf[ekey(e)] = e; });

var incident = {};
edges.forEach(function (e) {
  [0, 1].forEach(function (i) { (incident[e[i]] = incident[e[i]] || []).push(ekey(e)); });
});
var lgEdges = [];
['1', '2', '3', '4', '5', '6'].forEach(function (v) {
  var L = incident[v];
  for (var i = 0; i < L.length; i++) for (var j = i + 1; j < L.length; j++) lgEdges.push({ a: L[i], b: L[j], v: v });
});
var lgNbr = {};
edges.forEach(function (e) { lgNbr[ekey(e)] = []; });
lgEdges.forEach(function (le) {
  lgNbr[le.a].push({ o: le.b, v: le.v });
  lgNbr[le.b].push({ o: le.a, v: le.v });
});

var cliqueColor = { '1': '#2f6fd0', '2': '#8e44ad', '3': '#16a085', '4': '#e07b39', '5': '#c0392b', '6': '#6c7a89' };

var posC = {
  '2/3': [1382, 155], '1/3': [1548, 155], '2/5': [1228, 262], '1/5': [1408, 280],
  '1/4': [1458, 330], '1/6': [1582, 330], '4/5': [1247, 388], '4/6': [1458, 432]
};

function pA(v) { return [base[v][0] + offA[0], base[v][1] + offA[1]]; }
function pB(v) { return [base[v][0] + offB[0], base[v][1] + offB[1]]; }
function midB(e) { var a = pB(e[0]), b = pB(e[1]); return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]; }

/* ---------- static chrome ---------- */
var gChrome = D.group();
function txt(g, s, x, y, size, anchor, color, weight) {
  var t = g.text(s).font({ family: 'sans-serif', size: size, anchor: anchor || 'middle', weight: weight || 'normal' }).fill(color || INK);
  if (anchor === 'start') { t.attr('x', x); t.cy(y); t.attr('text-anchor', 'start'); t.attr('x', x); }
  else { t.cx(x); t.cy(y); }
  return t;
}
txt(gChrome, 'a)', 32, 40, 40, 'start');
txt(gChrome, 'b)', 600, 40, 40, 'start');
txt(gChrome, 'c)', 1172, 40, 40, 'start');
txt(gChrome, 'Original graph', 258, 40, 32);
txt(gChrome, 'Edge graph', 1408, 40, 32);

function arrow(x1, x2, y) {
  var g = gChrome.group();
  g.line(x1, y, x2 - 26, y).stroke({ color: GREY, width: 11, linecap: 'butt' });
  g.polygon([[x2 - 28, y - 17], [x2, y], [x2 - 28, y + 17]]).fill(GREY);
  return g;
}
arrow(405, 720, 512);
arrow(990, 1305, 512);
txt(gChrome, 'Add new node', 563, 550, 27);
txt(gChrome, 'at each original edge', 563, 584, 27);
txt(gChrome, 'Connect new nodes if', 1148, 550, 27);
txt(gChrome, 'original edges shared node', 1148, 584, 27);

/* ---------- panel groups ---------- */
var gA = D.group(), gB = D.group(), gC = D.group();

function makeNode(g, x, y, r, fill, label, fs) {
  var c = g.circle(r * 2).center(x, y).fill(fill).stroke({ color: INK, width: 3 });
  var t = g.text(label).font({ family: 'sans-serif', size: fs, anchor: 'middle' }).fill(INK);
  t.center(x, y);
  t.attr('pointer-events', 'none');
  return { c: c, t: t };
}

/* --- panel A --- */
var edgeElA = {}, nodeA = {};
edges.forEach(function (e) {
  var a = pA(e[0]), b = pA(e[1]), k = ekey(e);
  var ln = gA.line(a[0], a[1], b[0], b[1]).stroke({ color: INK, width: 3, linecap: 'round' });
  ln.css('cursor', 'pointer');
  var hit = gA.line(a[0], a[1], b[0], b[1]).stroke({ color: '#fff', width: 20, opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip('Original edge ' + e[0] + '–' + e[1] + '  →  edge-node ' + k, ev); });
  hit.on('mouseleave', hideTooltip);
  hit.on('click', function () { selectEdge(k); });
  edgeElA[k] = ln;
});
['1', '2', '3', '4', '5', '6'].forEach(function (v) {
  var p = pA(v);
  var n = makeNode(gA, p[0], p[1], 24, ORANGE, v, 24);
  n.c.css('cursor', 'pointer');
  n.c.on('mousemove', function (ev) {
    showTooltip('Vertex ' + v + ' — degree ' + incident[v].length + '  →  a ' + incident[v].length + '-clique in the edge graph', ev);
  });
  n.c.on('mouseleave', hideTooltip);
  n.c.on('click', function () {
    var d = incident[v].length;
    showPopup('Vertex ' + v + ' → a clique of size ' + d,
      'Vertex ' + v + ' touches ' + d + ' edges (' + incident[v].join(', ') + '). In the line graph those ' + d +
      ' nodes are all mutually connected, forming a complete clique with ' + (d * (d - 1) / 2) + ' edges. ' +
      'This is why a sparse graph with one hub produces a much denser edge graph.');
  });
  nodeA[v] = n;
});

/* --- panel B --- */
var segB = {}, tealB = {}, nodeB = {};
edges.forEach(function (e) {
  var a = pB(e[0]), b = pB(e[1]), m = midB(e), k = ekey(e);
  segB[k] = [
    gB.line(a[0], a[1], m[0], m[1]).stroke({ color: INK, width: 3, linecap: 'round' }),
    gB.line(m[0], m[1], b[0], b[1]).stroke({ color: INK, width: 3, linecap: 'round' })
  ];
});
['1', '2', '3', '4', '5', '6'].forEach(function (v) {
  var p = pB(v);
  nodeB[v] = makeNode(gB, p[0], p[1], 24, ORANGE, v, 24);
});
edges.forEach(function (e) {
  var m = midB(e), k = ekey(e);
  var n = makeNode(gB, m[0], m[1], 29, TEAL, k, 21);
  n.c.css('cursor', 'pointer');
  n.c.on('mousemove', function (ev) { showTooltip('Edge-node ' + k + ' sits on original edge ' + e[0] + '–' + e[1], ev); });
  n.c.on('mouseleave', hideTooltip);
  n.c.on('click', function () { selectEdge(k); });
  tealB[k] = n;
});

/* --- panel C --- */
var lgElC = [], tealC = {};
lgEdges.forEach(function (le) {
  var a = posC[le.a], b = posC[le.b];
  var ln = gC.line(a[0], a[1], b[0], b[1]).stroke({ color: INK, width: 3, linecap: 'round' });
  var hit = gC.line(a[0], a[1], b[0], b[1]).stroke({ color: '#fff', width: 16, opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip(le.a + ' — ' + le.b + ' : both original edges meet at vertex ' + le.v, ev); });
  hit.on('mouseleave', hideTooltip);
  le.el = ln;
  lgElC.push(le);
});
edges.forEach(function (e) {
  var k = ekey(e), p = posC[k];
  var n = makeNode(gC, p[0], p[1], 29, TEAL, k, 21);
  n.c.css('cursor', 'pointer');
  n.c.on('mousemove', function (ev) { showTooltip('Edge-node ' + k + ' — degree ' + lgNbr[k].length + ' in the edge graph', ev); });
  n.c.on('mouseleave', hideTooltip);
  n.c.on('click', function () { selectEdge(k); });
  tealC[k] = n;
});

/* ---------- state ---------- */
var phase = 'full', viewMode = 'Both', selected = null;

function panelOpacity() {
  var oA = 1, oB = 1, oC = 1;
  if (phase === 'original') { oB = 0; oC = 0; }
  else if (phase === 'placeNodes') { oC = 0; }
  if (viewMode === 'Original') { oB = Math.min(oB, 0.16); oC = Math.min(oC, 0.16); }
  else if (viewMode === 'Edge graph') { oA = Math.min(oA, 0.16); oB = Math.min(oB, 0.16); }
  return [oA, oB, oC];
}

function styleAll() {
  var sel = selected;
  edges.forEach(function (e) {
    var k = ekey(e), on = (k === sel);
    var col = !sel ? INK : (on ? ACCENT : FAINT);
    edgeElA[k].stroke({ color: col, width: on ? 7 : 3 });
    segB[k].forEach(function (s) { s.stroke({ color: col, width: on ? 6 : 3 }); });
  });
  ['1', '2', '3', '4', '5', '6'].forEach(function (v) {
    var end = sel && edgeOf[sel].indexOf(v) >= 0;
    var fill = !sel ? ORANGE : (end ? ORANGE : ORANGE_DIM);
    nodeA[v].c.fill(fill).stroke({ color: end ? ACCENT : INK, width: end ? 5 : 3 });
    nodeB[v].c.fill(fill).stroke({ color: end ? ACCENT : INK, width: end ? 5 : 3 });
  });
  edges.forEach(function (e) {
    var k = ekey(e), on = (k === sel);
    var adj = false;
    if (sel) for (var i = 0; i < lgNbr[sel].length; i++) if (lgNbr[sel][i].o === k) adj = true;
    var fill = !sel ? TEAL : ((on || adj) ? TEAL : TEAL_DIM);
    tealB[k].c.fill(fill).stroke({ color: on ? ACCENT : INK, width: on ? 6 : 3 });
    tealC[k].c.fill(fill).stroke({ color: on ? ACCENT : INK, width: on ? 6 : 3 });
  });
  lgElC.forEach(function (le) {
    var inc = sel && (le.a === sel || le.b === sel);
    var col;
    if (sel) col = inc ? ACCENT : '#e6e6e6';
    else col = (phase === 'connectShared') ? cliqueColor[le.v] : INK;
    le.el.stroke({ color: col, width: inc ? 6 : 3 });
  });
}

function applyState() {
  var o = panelOpacity();
  [[gA, o[0]], [gB, o[1]], [gC, o[2]]].forEach(function (pair) {
    pair[0].animate(240).attr('opacity', pair[1]);
    pair[0].attr('pointer-events', pair[1] < 0.3 ? 'none' : 'all');
  });
  syncPhaseButtons();
  styleAll();
  updateReadout();
}

function syncPhaseButtons() {
  ['full', 'original', 'placeNodes', 'connectShared', 'edgeGraph'].forEach(function (p) {
    var b = document.getElementById('phaseBtn-' + p);
    if (b) b.className = (p === phase) ? 'active' : '';
  });
  var s = document.getElementById('viewModeInput');
  if (s && s.value !== viewMode) s.value = viewMode;
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  if (selected) {
    var e = edgeOf[selected];
    var byV = {};
    lgNbr[selected].forEach(function (n) { (byV[n.v] = byV[n.v] || []).push(n.o); });
    var parts = Object.keys(byV).map(function (v) { return 'via vertex ' + v + ': ' + byV[v].join(', '); });
    el.innerHTML = '<b>Edge ' + e[0] + '–' + e[1] + ' → node ' + selected + '</b><br>' +
      parts.join('<br>') + '<br>degree in the edge graph = ' + lgNbr[selected].length + '.';
  } else if (phase === 'connectShared') {
    el.innerHTML = 'New edges are coloured by the shared vertex: vertex&nbsp;1 (degree&nbsp;4) alone creates a 6-edge clique; vertices 4 and 5 give 3 edges each; 2, 3 and 6 give one each — 15 in total.';
  } else {
    el.innerHTML = '8 original edges → 8 edge-nodes; 15 edge-graph edges.';
  }
}

function setPhase(p) { phase = p; applyState(); }
function toggle_viewMode(v) { viewMode = v; applyState(); }
function trigger_clearSel() { selected = null; styleAll(); updateReadout(); }
function selectEdge(k) { selected = (selected === k) ? null : k; styleAll(); updateReadout(); }

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'The full transformation',
    narration: 'Left: the original graph. Middle: a teal node dropped on every edge. Right: the finished edge (line) graph. Step forward to build it.',
    state: { buildPhase: 'full', viewMode: 'Both' }
  },
  {
    title: 'The original graph',
    narration: 'Six orange vertices joined by eight undirected edges. Note the hub: vertex 1 touches four of the eight edges.',
    state: { buildPhase: 'original', viewMode: 'Original' }
  },
  {
    title: 'Promote every edge to a node',
    narration: 'A teal node is dropped onto each original edge and named by its endpoints, so 1-3 becomes "1/3". Eight edges give exactly eight new nodes.',
    state: { buildPhase: 'placeNodes', viewMode: 'Both' }
  },
  {
    title: 'Inherit adjacency from shared endpoints',
    narration: 'Two teal nodes get connected whenever their original edges met at a vertex. Every original vertex of degree d turns into a fully connected clique of d teal nodes (colour-coded here).',
    state: { buildPhase: 'connectShared', viewMode: 'Both' }
  },
  {
    title: 'Read off the edge graph',
    narration: 'Dropping the orange scaffolding leaves the line graph: 8 nodes and 15 edges. Click any original edge or teal node to see which clique it belongs to.',
    state: { buildPhase: 'edgeGraph', viewMode: 'Edge graph' }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  selected = null;
  phase = s.state.buildPhase;
  viewMode = s.state.viewMode;
  var sel = document.getElementById('viewModeInput');
  if (sel) sel.value = viewMode;
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  applyState();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
