/* ---------- geometry ---------- */
var base = {
  '1': [445, 208], '2': [117, 172], '3': [308, 100],
  '4': [158, 430], '5': [42, 325], '6': [455, 430]
};
var offA = [22, 0], offB = [594, -4];
var edges = [['1', '3'], ['2', '3'], ['2', '5'], ['1', '5'], ['1', '4'], ['4', '5'], ['1', '6'], ['4', '6']];

/* teal node positions in panel b: on the edge, bulging outward so the bead
   chain visibly curves (as in the source figure) */
var tealBase = {
  '2/3': [203, 118], '1/3': [393, 141], '2/5': [57, 249], '1/5': [236, 270],
  '1/4': [302, 320], '4/5': [81, 392], '1/6': [460, 318], '4/6': [307, 435]
};

/* panel c layout (only teal nodes, relative positions preserved) */
var posC = {
  '2/3': [1256, 146], '1/3': [1468, 150], '2/5': [1218, 254], '1/5': [1392, 259],
  '1/4': [1452, 328], '1/6': [1558, 316], '4/5': [1216, 384], '4/6': [1392, 430]
};

var R_V = 32, R_E = 36, FS_V = 35, FS_E = 29;
var SW_NODE = 5, SW_EDGE = 4.6;

function ekey(e) { return e[0] + '/' + e[1]; }
var edgeOf = {};
edges.forEach(function (e) { edgeOf[ekey(e)] = e; });

var incident = {};
edges.forEach(function (e) {
  [0, 1].forEach(function (i) { (incident[e[i]] = incident[e[i]] || []).push(ekey(e)); });
});
var verts = ['1', '2', '3', '4', '5', '6'];
var lgEdges = [];
verts.forEach(function (v) {
  var L = incident[v];
  for (var i = 0; i < L.length; i++) for (var j = i + 1; j < L.length; j++) lgEdges.push({ a: L[i], b: L[j], v: v });
});
var lgNbr = {};
edges.forEach(function (e) { lgNbr[ekey(e)] = []; });
lgEdges.forEach(function (le) {
  lgNbr[le.a].push({ o: le.b, v: le.v });
  lgNbr[le.b].push({ o: le.a, v: le.v });
});
var cliqueColor = { '1': '#2f6fd0', '2': '#8e44ad', '3': '#16a085', '4': '#e07b39', '5': '#c0392b', '6': '#6c7a89' };

function pA(v) { return [base[v][0] + offA[0], base[v][1] + offA[1]]; }
function pB(v) { return [base[v][0] + offB[0], base[v][1] + offB[1]]; }
function tB(k) { return [tealBase[k][0] + offB[0], tealBase[k][1] + offB[1]]; }

/* ---------- static chrome ---------- */
var gChrome = D.group();
function label(g, s, x, y, size, anchor, color) {
  var t = g.text(s).font({ family: 'sans-serif', size: size, anchor: anchor || 'middle' }).fill(color || INK);
  if (anchor === 'start') { t.attr('text-anchor', 'start'); t.attr('x', x); t.cy(y); }
  else { t.cx(x); t.cy(y); }
  t.attr('pointer-events', 'none');
  return t;
}
label(gChrome, 'a)', 8, 36, 46, 'start', '#2a2a2a');
label(gChrome, 'b)', 590, 36, 46, 'start', '#2a2a2a');
label(gChrome, 'c)', 1156, 36, 46, 'start', '#2a2a2a');
label(gChrome, 'Original graph', 268, 34, 37);
label(gChrome, 'Edge graph', 1402, 34, 37);

function arrow(x1, x2, y) {
  var g = gChrome.group();
  g.line(x1, y, x2 - 28, y).stroke({ color: GREY, width: 12, linecap: 'butt' });
  g.polygon([[x2 - 30, y - 18], [x2, y], [x2 - 30, y + 18]]).fill(GREY);
}
arrow(398, 712, 496);
arrow(994, 1308, 496);
label(gChrome, 'Add new node', 556, 540, 31);
label(gChrome, 'at each original edge', 556, 576, 31);
label(gChrome, 'Connect new nodes if', 1152, 540, 31);
label(gChrome, 'original edges shared node', 1152, 576, 31);

/* ---------- panels ---------- */
var gA = D.group(), gB = D.group(), gC = D.group();

function makeNode(g, x, y, r, fill, text, fs) {
  var c = g.circle(r * 2).center(x, y).fill(fill).stroke({ color: INK, width: SW_NODE });
  var t = g.text(text).font({ family: 'sans-serif', size: fs, anchor: 'middle' }).fill(INK);
  t.center(x, y);
  t.attr('pointer-events', 'none');
  return { c: c, t: t };
}

/* --- panel a --- */
var edgeElA = {}, nodeA = {};
edges.forEach(function (e) {
  var a = pA(e[0]), b = pA(e[1]), k = ekey(e);
  var ln = gA.line(a[0], a[1], b[0], b[1]).stroke({ color: INK, width: SW_EDGE, linecap: 'round' });
  var hit = gA.line(a[0], a[1], b[0], b[1]).stroke({ color: '#fff', width: 24, opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip('Original edge ' + e[0] + '–' + e[1] + '  →  edge-node ' + k, ev); });
  hit.on('mouseleave', hideTooltip);
  hit.on('click', function () { selectEdge(k); });
  edgeElA[k] = ln;
});
verts.forEach(function (v) {
  var p = pA(v);
  var n = makeNode(gA, p[0], p[1], R_V, ORANGE, v, FS_V);
  n.c.css('cursor', 'pointer');
  n.c.on('mousemove', function (ev) {
    showTooltip('Vertex ' + v + ' — degree ' + incident[v].length + '  →  a ' + incident[v].length + '-clique in the edge graph', ev);
  });
  n.c.on('mouseleave', hideTooltip);
  n.c.on('click', function () {
    var d = incident[v].length;
    showPopup('Vertex ' + v + ' → a clique of size ' + d,
      'Vertex ' + v + ' touches ' + d + ' edges (' + incident[v].join(', ') + '). In the line graph those ' + d +
      ' nodes become mutually connected — a complete clique with ' + (d * (d - 1) / 2) + ' edges. ' +
      'This is why a sparse graph with one hub produces a much denser edge graph.');
  });
  nodeA[v] = n;
});

/* --- panel b --- */
var segB = {}, tealB = {}, nodeB = {};
edges.forEach(function (e) {
  var a = pB(e[0]), b = pB(e[1]), m = tB(ekey(e)), k = ekey(e);
  segB[k] = [
    gB.line(a[0], a[1], m[0], m[1]).stroke({ color: INK, width: SW_EDGE, linecap: 'round' }),
    gB.line(m[0], m[1], b[0], b[1]).stroke({ color: INK, width: SW_EDGE, linecap: 'round' })
  ];
});
verts.forEach(function (v) {
  var p = pB(v);
  nodeB[v] = makeNode(gB, p[0], p[1], R_V, ORANGE, v, FS_V);
});
edges.forEach(function (e) {
  var k = ekey(e), m = tB(k);
  var n = makeNode(gB, m[0], m[1], R_E, TEAL, k, FS_E);
  n.c.css('cursor', 'pointer');
  n.c.on('mousemove', function (ev) { showTooltip('Edge-node ' + k + ' sits on original edge ' + e[0] + '–' + e[1], ev); });
  n.c.on('mouseleave', hideTooltip);
  n.c.on('click', function () { selectEdge(k); });
  tealB[k] = n;
});

/* --- panel c --- */
var lgElC = [], tealC = {};
lgEdges.forEach(function (le) {
  var a = posC[le.a], b = posC[le.b];
  var ln = gC.line(a[0], a[1], b[0], b[1]).stroke({ color: INK, width: SW_EDGE, linecap: 'round' });
  var hit = gC.line(a[0], a[1], b[0], b[1]).stroke({ color: '#fff', width: 16, opacity: 0 }).css('cursor', 'pointer');
  hit.on('mousemove', function (ev) { showTooltip(le.a + ' — ' + le.b + ' : both original edges meet at vertex ' + le.v, ev); });
  hit.on('mouseleave', hideTooltip);
  le.el = ln;
  lgElC.push(le);
});
edges.forEach(function (e) {
  var k = ekey(e), p = posC[k];
  var n = makeNode(gC, p[0], p[1], R_E, TEAL, k, FS_E);
  n.c.css('cursor', 'pointer');
  n.c.on('mousemove', function (ev) { showTooltip('Edge-node ' + k + ' — degree ' + lgNbr[k].length + ' in the edge graph', ev); });
  n.c.on('mouseleave', hideTooltip);
  n.c.on('click', function () { selectEdge(k); });
  tealC[k] = n;
});

/* ---------- state ---------- */
var phase = 'full', viewMode = 'Both', selected = null, cliqueOn = false;

function panelOpacity() {
  var oA = 1, oB = 1, oC = 1;
  if (phase === 'original') { oB = 0; oC = 0; }
  else if (phase === 'placeNodes') { oC = 0; }
  if (viewMode === 'Original') { oB = Math.min(oB, 0.16); oC = Math.min(oC, 0.16); }
  else if (viewMode === 'Edge graph') { oA = Math.min(oA, 0.16); oB = Math.min(oB, 0.16); }
  return [oA, oB, oC];
}

function styleAll() {
  var sel = selected;
  edges.forEach(function (e) {
    var k = ekey(e), on = (k === sel);
    var col = !sel ? INK : (on ? ACCENT : FAINT);
    edgeElA[k].stroke({ color: col, width: on ? 8 : SW_EDGE });
    segB[k].forEach(function (s) { s.stroke({ color: col, width: on ? 7.5 : SW_EDGE }); });
  });
  verts.forEach(function (v) {
    var end = sel && edgeOf[sel].indexOf(v) >= 0;
    var fill = !sel ? ORANGE : (end ? ORANGE : ORANGE_DIM);
    nodeA[v].c.fill(fill).stroke({ color: end ? ACCENT : INK, width: end ? 7 : SW_NODE });
    nodeB[v].c.fill(fill).stroke({ color: end ? ACCENT : INK, width: end ? 7 : SW_NODE });
  });
  edges.forEach(function (e) {
    var k = ekey(e), on = (k === sel);
    var adj = false;
    if (sel) for (var i = 0; i < lgNbr[sel].length; i++) if (lgNbr[sel][i].o === k) adj = true;
    var fill = !sel ? TEAL : ((on || adj) ? TEAL : TEAL_DIM);
    tealB[k].c.fill(fill).stroke({ color: on ? ACCENT : INK, width: on ? 7.5 : SW_NODE });
    tealC[k].c.fill(fill).stroke({ color: on ? ACCENT : INK, width: on ? 7.5 : SW_NODE });
  });
  lgElC.forEach(function (le) {
    var inc = sel && (le.a === sel || le.b === sel);
    var col;
    if (sel) col = inc ? ACCENT : '#e8e8e8';
    else col = cliqueOn ? cliqueColor[le.v] : INK;
    le.el.stroke({ color: col, width: inc ? 7.5 : SW_EDGE });
  });
}

function applyState() {
  var o = panelOpacity();
  [[gA, o[0]], [gB, o[1]], [gC, o[2]]].forEach(function (pair) {
    pair[0].animate(240).attr('opacity', pair[1]);
    pair[0].attr('pointer-events', pair[1] < 0.3 ? 'none' : 'all');
  });
  syncControls();
  styleAll();
  updateReadout();
}

function syncControls() {
  ['full', 'original', 'placeNodes', 'connectShared', 'edgeGraph'].forEach(function (p) {
    var b = document.getElementById('phaseBtn-' + p);
    if (b) b.className = (p === phase) ? 'active' : '';
  });
  var s = document.getElementById('viewModeInput');
  if (s && s.value !== viewMode) s.value = viewMode;
  var c = document.getElementById('cliqueColorInput');
  if (c && c.checked !== cliqueOn) c.checked = cliqueOn;
}

function updateReadout() {
  var el = document.getElementById('readout');
  if (!el) return;
  if (selected) {
    var e = edgeOf[selected];
    var byV = {};
    lgNbr[selected].forEach(function (n) { (byV[n.v] = byV[n.v] || []).push(n.o); });
    var parts = Object.keys(byV).map(function (v) { return 'via vertex ' + v + ': ' + byV[v].join(', '); });
    el.innerHTML = '<b>Edge ' + e[0] + '–' + e[1] + ' → node ' + selected + '</b><br>' +
      parts.join('<br>') + '<br>degree in the edge graph = ' + lgNbr[selected].length + '.';
  } else if (phase === 'connectShared' || cliqueOn) {
    el.innerHTML = 'Each vertex becomes a clique: vertex&nbsp;1 (degree&nbsp;4) alone creates a 6-edge clique; vertices 4 and 5 give 3 edges each; 2, 3 and 6 give one each — 15 in total.';
  } else {
    el.innerHTML = '8 original edges → 8 edge-nodes; 15 edge-graph edges.';
  }
}

function setPhase(p) {
  phase = p;
  if (p !== 'connectShared') cliqueOn = false;
  applyState();
}
function toggle_viewMode(v) { viewMode = v; applyState(); }
function toggle_cliqueColor(on) { cliqueOn = on; styleAll(); updateReadout(); }
function trigger_clearSel() { selected = null; styleAll(); updateReadout(); }
function selectEdge(k) { selected = (selected === k) ? null : k; styleAll(); updateReadout(); }

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'The full transformation',
    narration: 'Left: the original graph. Middle: a teal node dropped on every edge. Right: the finished edge (line) graph. Step forward to build it.',
    state: { buildPhase: 'full', viewMode: 'Both', clique: false }
  },
  {
    title: 'The original graph',
    narration: 'Six orange vertices joined by eight undirected edges. Note the hub: vertex 1 touches four of the eight edges.',
    state: { buildPhase: 'original', viewMode: 'Original', clique: false }
  },
  {
    title: 'Promote every edge to a node',
    narration: 'A teal node is dropped onto each original edge and named by its endpoints, so 1-3 becomes "1/3". Eight edges give exactly eight new nodes.',
    state: { buildPhase: 'placeNodes', viewMode: 'Both', clique: false }
  },
  {
    title: 'Inherit adjacency from shared endpoints',
    narration: 'Two teal nodes get connected whenever their original edges met at a vertex. Every original vertex of degree d turns into a fully connected clique of d teal nodes (colour-coded here — untick the box for the plain figure).',
    state: { buildPhase: 'connectShared', viewMode: 'Both', clique: true }
  },
  {
    title: 'Read off the edge graph',
    narration: 'Dropping the orange scaffolding leaves the line graph: 8 nodes and 15 edges. Click any original edge or teal node to see which cliques it belongs to.',
    state: { buildPhase: 'edgeGraph', viewMode: 'Edge graph', clique: false }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var s = steps[stepIdx];
  selected = null;
  phase = s.state.buildPhase;
  viewMode = s.state.viewMode;
  cliqueOn = !!s.state.clique;
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + steps.length;
  applyState();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
